app.post("/orders/:id/cancel", async (req, res) => {
  const order = orders.get(req.params.id);
  if (!order) return res.status(404).json({ error: "order not found" });
  if (order.status === "cancelled") return res.status(409).json({ error: "order already cancelled" });
  if (PAYMENTS_URL) {
    const refund = await post(`${PAYMENTS_URL}/payments/${order.paymentId}/refund`, {});
    if (refund.status !== 200) return res.status(502).json({ error: "refund failed" });
  }
  order.status = "cancelled";
  res.json(order);
});

